import numpy as np

def big_move_days(returns, volumes, move, min_volume):
    r = np.asarray(returns, dtype=float)
    v = np.asarray(volumes, dtype=float)
    mask = (np.abs(r) >= move) | (v >= min_volume)
    return np.flatnonzero(mask).tolist()
